#include <iostream>
#include <random>
#include <vector>

int main() {
    std::mt19937 uno{43};
    std::mt19937 dos{43};
    std::uniform_int_distribution<int> reparto_uno{1, 8};
    std::uniform_int_distribution<int> reparto_dos{1, 8};
    std::vector<int> primera;
    std::vector<int> segunda;
    for (int i{0}; i < 5; ++i) {
        primera.push_back(reparto_uno(uno));
        segunda.push_back(reparto_dos(dos));
    }
    std::cout << (primera == segunda) << ':' << primera.size();
    return 0;
}

#include <iostream>
