    std::uniform_int_distribution<int> b{2, 9};
    std::vector<int> todos;
    std::vector<int> por_partes;
    for (int i{0}; i < 6; ++i) {
        todos.push_back(a(entero));
    }
    for (int i{0}; i < 2; ++i) {
        por_partes.push_back(b(dividido));
    }
    for (int i{0}; i < 4; ++i) {
        por_partes.push_back(b(dividido));
    }
    std::cout << (todos == por_partes) << ':' << por_partes.size();
    return 0;
}

#include <iostream>
#include <random>
#include <vector>

int main() {
    std::mt19937 motor{97};
    std::uniform_int_distribution<int> elegir{-4, 4};
    std::vector<int> antes;
    std::vector<int> despues;
    for (int i{0}; i < 4; ++i) {
        antes.push_back(elegir(motor));
    }
    motor.seed(97);
    elegir.reset();
    for (int i{0}; i < 4; ++i) {
        despues.push_back(elegir(motor));
    }
    std::cout << (antes == despues);
    return 0;
}

