#include <iostream>
#include <random>
#include <vector>

int main() {
    std::mt19937 primero{53};
    std::mt19937 segundo{53};
    std::uniform_int_distribution<int> a{1, 9};
    std::uniform_int_distribution<int> b{1, 9};
    std::vector<int> completa;
    std::vector<int> lotes;
    for (int i{0}; i < 6; ++i) {
        completa.push_back(a(primero));
    }
    for (int i{0}; i < 2; ++i) {
        lotes.push_back(b(segundo));
    }
    for (int i{0}; i < 4; ++i) {
        lotes.push_back(b(segundo));
    }
    std::cout << "In batches:" << (completa == lotes) << '\n';
    primero.seed(53);
    a.reset();
    std::vector<int> repetida;
    for (int i{0}; i < 6; ++i) {
        repetida.push_back(a(primero));
    }
    std::cout << "Restart:" << (completa == repetida);
    return 0;
}
